let embeddedRule0061: RuleEntry = RuleEntry(
    id: "dmg_ch09_calculating_thac0",
    book: "DMG",
    chapterNumber: 9,
    chapterTitle: "Combat",
    breadcrumbs: "Dungeon Master's Guide > Chapter 9: Combat > Calculating THAC0",
    topic: "Calculating THAC0",
    ruleType: "core_rule",
    summary: "To make an attack roll, the character's THAC0 must be known. This depends on the group and level, if the attacker is a player character or NPC, or the Hit Dice if the attacker is a monster or an animal.",
    content: "To make an attack roll, the character's THAC0 must be known. This depends on the group and level, if the attacker is a player character or NPC, or the Hit Dice if the attacker is a monster or an animal. All 1st-level characters have THAC0s of 20.\n\nFor a character of level 1 through level 20, consult Table 38. This table lists the THAC0 number of each group through 20th level, so players don't have to perform any calculations.\n\nFor a character higher than 20th level, find the Improvement Rate for the character's group in Table 37. There you'll find the number of levels a character must advance to reduce his THAC0 by 1 or more points. Calculate the character's THAC0 according to his level. A priest, for example, improves by two for every three levels he advances. A 5th level cleric would have a THAC0 of 18. A rogue (a thief or bard) improves one point every two levels. A 17th-level rogue would have a THAC0 of 12. Table 38 lists the THAC0 number of each group at each level.\n\nCreatures do not have character classes and levels, so they calculate THAC0s differently, basing it on the Hit Dice of the creature. Table 39 lists the THAC0 number for monsters having various numbers of Hit Dice. When a creature has three or more points added to its Hit Dice, count another die when consulting the table.\n\n[TABLE_REF: Table 37: THAC0 Advancement]\n\n[TABLE_REF: Table 38: Calculated THAC0S]\n\n[TABLE_REF: Table 39: Creature THAC0]",
    tables: [
        RuleTable(
                tableNumber: "Table 37",
                title: "Table 37: THAC0 Advancement",
                headers: ["Group", "Improvement Rate Points/Level"],
                rows: [
                    ["Priest", "2/3"],
                    ["Rogue", "1/2"],
                    ["Warrior", "1/1"],
                    ["Wizard", "1/3"]
                ]
            ),
